const CHALLENGE = "july-2026";
const CHALLENGE_START = new Date("2026-07-01T00:00:00");
const SITE = "https://heatherlynwilson.com";

// Embedded email content for both tracks
const EMAILS_FULL_BIBLE = [{"day":1,"subject":"Day 1 — Here we go. Genesis.","reading":"Genesis 1–50","body":"Good morning.\n\nToday is the day. You signed up for this. I signed up for this. And right now, hundreds of us are opening to Genesis 1 together.\n\nYes, the whole book of Genesis today. Fifty chapters. I am not going to sugarcoat it. That is a lot. But here is what I want you to know. Genesis reads fast. It is all story. Creation, the flood, Abraham, Isaac, Jacob, Joseph. You will get pulled in.\n\nDo not worry about understanding every detail. Do not stop to study. Just read. Let the words wash over you. You are not writing a paper. You are meeting God in His Word.\n\nIf you cannot finish all 50 chapters today, that is okay. Read what you can. Mark where you stopped. Come back to it. The goal is not perfection. The goal is showing up.\n\nI am reading alongside you today.\n\nHeather"},{"day":2,"subject":"Day 2 — Slavery, plagues, and a God who shows up","reading":"Exodus 1–40","body":"Good morning.\n\nYesterday was Genesis. Today is Exodus. And the tone shifts fast.\n\nThe people of God go from favor to slavery in the first chapter. And then God raises up Moses, a man who did not want the job, to lead them out.\n\nHere is what stood out to me when I read this. God did not wait for Moses to be ready. He did not wait for the people to have it together. He showed up because He heard them crying. That was enough.\n\nToday you will read about plagues and Passover and the Red Sea and the Ten Commandments and the building of the tabernacle. It is a full book. Take it one chapter at a time.\n\nYou are on Day 2. You showed up again. That matters.\n\nHeather"},{"day":3,"subject":"Day 3 — The one nobody looks forward to","reading":"Leviticus 1–27","body":"Good morning.\n\nLeviticus. I know.\n\nThis is the book people quit on. All the rules about sacrifices and skin diseases and what to eat and what not to eat. It feels like reading a manual for a world that does not exist anymore.\n\nBut here is what I want you to see today. Every single rule in this book exists because God wanted to be close to His people. He was not trying to make their lives harder. He was teaching them how to live near a holy God and survive it.\n\nThe whole book is God saying, I want to dwell among you. Here is how.\n\nSo push through it. Read it fast if you need to. But do not skip it. There is something in there for you today.\n\nIf you are still going after Leviticus, you can handle anything this month throws at you.\n\nHeather"},{"day":4,"subject":"Day 4 — Wandering starts here","reading":"Numbers 1–36","body":"Good morning.\n\nNumbers starts with a census. Then it turns into the story of a people who could not stop complaining.\n\nGod had rescued them. Parted the sea. Fed them from the sky. And they still grumbled. They still wanted to go back to Egypt. They still doubted.\n\nAnd honestly, I see myself in them more than I want to admit.\n\nHow many times has God shown up in my life and I still doubted the next thing? How many times has He provided and I still worried about tomorrow?\n\nThat is the gift of reading the whole Bible like this. You start to see yourself in the story. Not always in the heroes. Sometimes in the people who could not stop looking back.\n\nKeep going. You are almost through the wilderness.\n\nHeather"},{"day":5,"subject":"Day 5 — Moses says goodbye","reading":"Deuteronomy 1–34","body":"Good morning.\n\nDeuteronomy is Moses giving his final speech. He knows he is not going into the Promised Land. He knows his time is almost up. And he spends his last days reminding the people of everything God has done.\n\nRemember. Do not forget. Tell your children. Remember.\n\nHe says it over and over. Because he knows what happens when people forget.\n\nThis book is long. Parts of it repeat what you have already read. But pay attention to the heart behind it. This is a man who walked with God for forty years, standing at the edge of something he will never see, and his last words are not about himself. They are about making sure the next generation does not lose what matters.\n\nYou are five days in. You have read five entire books of the Bible. That is no small thing.\n\nHeather"},{"day":6,"subject":"Day 6 — They finally get there","reading":"Joshua 1–24","body":"Good morning.\n\nAfter forty years in the wilderness, they cross into the Promised Land. Joshua is in charge now. And the very first thing God says to him is be strong and courageous.\n\nHe does not say be smart. He does not say have a plan. He says be strong and do not be afraid.\n\nJoshua is full of battles and victories and territory being claimed. It moves fast. And there is something satisfying about reading it after all that wandering in Numbers and Deuteronomy.\n\nThey made it. Not because they were perfect. Because God kept His promise.\n\nYou are almost a week in. Be strong and keep going.\n\nHeather"},{"day":7,"subject":"Day 7 — One week done","reading":"Judges 1–21, Ruth 1–4","body":"Good morning.\n\nYou have been reading the Bible for a full week. Seven days. That is worth pausing on.\n\nToday is Judges and Ruth. They go together. Judges is the story of Israel falling apart. Over and over they turn away from God, things go badly, they cry out, God raises up a judge to save them, and then they do it all again. It is exhausting to read because the cycle never stops.\n\nAnd then Ruth shows up. Right in the middle of all that chaos, this quiet little story about faithfulness and kindness and a woman who refused to leave.\n\nRuth is only four chapters. But after Judges, it hits different.\n\nSometimes God is in the big dramatic rescues. And sometimes He is in the quiet loyalty of one person who just stayed.\n\nOne week down. I am proud of you.\n\nHeather"},{"day":8,"subject":"Day 8 — A boy in the temple hears God's voice","reading":"1 Samuel 1–31","body":"Good morning.\n\nToday is one of my favorite books. First Samuel. A woman named Hannah prays for a son. God gives her Samuel. She gives him back to God. And then this little boy lying in the temple hears the voice of God and does not even know what it is.\n\nThat image has always stayed with me. God speaking to a child in the dark. And the child saying, speak Lord, your servant is listening.\n\nThen you get Saul. Then David. The giant. The friendship with Jonathan. The jealousy. The running. The caves.\n\nFirst Samuel has everything. It reads like a novel. Enjoy it today.\n\nHeather"},{"day":9,"subject":"Day 9 — David at his best and worst","reading":"2 Samuel 1–24","body":"Good morning.\n\nSecond Samuel is David's reign. And it is complicated.\n\nThis is the man after God's own heart. The one who danced before the Lord. The one who wrote half the Psalms. And this is also the man who saw Bathsheba and everything fell apart.\n\nI think we want our Bible heroes to stay heroes. But they do not. David is proof that you can love God deeply and still make devastating choices.\n\nThe thing that sets David apart is not that he never sinned. It is that he always came back. He repented. He grieved. He did not pretend.\n\nThat is the lesson I take from today. Not that I will get it right every time. But that when I do not, I can still come back.\n\nHeather"},{"day":10,"subject":"Day 10 — Solomon builds the temple and then loses his way","reading":"1 Kings 1–22","body":"Good morning.\n\nFirst Kings starts with Solomon, the wisest man who ever lived, building the most magnificent temple the world had ever seen. And it ends with him worshiping other gods because of the women he married.\n\nThat is the tragedy of this book. The man who had everything, wisdom, wealth, peace, could not hold onto the one thing that mattered.\n\nAnd then the kingdom splits. Ten tribes go north. Two stay south. And it never comes back together.\n\nYou will also meet Elijah today. One of the greatest prophets in Scripture. Standing alone against 450 prophets of Baal on Mount Carmel. And then running away and hiding under a tree the very next day.\n\nThe Bible is honest about people. That is one of the reasons I trust it.\n\nYou are ten days in. A third of the way through this challenge.\n\nHeather"},{"day":11,"subject":"Day 11 — Everything falls apart","reading":"2 Kings 1–25","body":"Good morning.\n\nSecond Kings is hard. You are watching two kingdoms fall. Bad king after bad king. A few good ones scattered in. Prophets warning. Nobody listening.\n\nAnd then Babylon comes. Jerusalem falls. The temple that Solomon built gets destroyed. The people are carried into exile.\n\nIt is heavy. But do not rush past the grief of it. This matters. Because the rest of the Bible, the prophets, the Psalms, even the New Testament, is all shaped by this moment. Everything changed when the temple fell.\n\nSome days the reading is going to be hard. Today is one of those days. But you are still here. And that matters.\n\nHeather"},{"day":12,"subject":"Day 12 — The same story, different angle","reading":"1 Chronicles 1–29","body":"Good morning.\n\nFirst Chronicles covers a lot of the same ground as Samuel and Kings. You are going to recognize stories. You might wonder why it is here.\n\nHere is what I want you to notice. Chronicles was written after the exile. The people had lost everything and come back. And someone sat down and retold their history, but this time with an emphasis on worship. On the temple. On what God had done.\n\nWhen you lose everything and then look back, you see different things. You see the hand of God in places you missed the first time.\n\nYes, the genealogies at the beginning are long. Power through them. The rest of the book will reward you.\n\nAlmost two weeks in. You are doing this.\n\nHeather"},{"day":13,"subject":"Day 13 — The rise and fall, one more time","reading":"2 Chronicles 1–36","body":"Good morning.\n\nSecond Chronicles takes you from Solomon's glory all the way to the exile. Again. But watch for the kings you missed before. Hezekiah, who prayed and God moved. Josiah, who found the Book of the Law and wept because his people had wandered so far.\n\nAnd notice the very last verse. Cyrus, king of Persia, lets the people go home. After seventy years of exile, someone opens the door.\n\nGod does not forget His promises. Even when it takes seventy years.\n\nThirteen days. You have read thirteen books of the Bible. Let that sink in.\n\nHeather"},{"day":14,"subject":"Day 14 — They go home","reading":"Ezra 1–10, Nehemiah 1–13, Esther 1–10","body":"Good morning. Two weeks in.\n\nToday is three books. Ezra, Nehemiah, and Esther. They are shorter and they move fast.\n\nEzra is about rebuilding the temple. Nehemiah is about rebuilding the wall. Esther is about a woman who saved her people by showing up when it mattered most.\n\nAll three books are about restoration. About going back to the rubble and building something again. About courage in hard places.\n\nIf you are feeling the weight of this challenge right now, if two weeks in feels like a lot, these three books are for you today. Because they are proof that broken things get rebuilt. And it starts with one person who says I will go.\n\nYou are halfway to halfway. Keep going.\n\nHeather"},{"day":15,"subject":"Day 15 — The hardest question in the Bible","reading":"Job 1–42","body":"Good morning.\n\nJob. The whole thing. Forty-two chapters.\n\nA man who did everything right loses everything. His children. His health. His wealth. His friends show up and tell him he must have done something wrong. He insists he did not. And for most of the book, God is silent.\n\nAnd then God speaks. And He does not answer the question. He does not explain why. He just says, I am God and you are not. Where were you when I laid the foundations of the earth?\n\nThat answer is not satisfying to our human brains. But it is the truth. We do not always get to know why. We just get to know who.\n\nThis book will wreck you if you let it. Let it.\n\nYou are almost halfway through the Bible.\n\nHeather"},{"day":16,"subject":"Day 16 — Halfway. You made it to the Psalms.","reading":"Psalms 1–50","body":"Good morning.\n\nSixteen days in. You are officially past the halfway mark of this challenge. And today you land in the Psalms.\n\nThe Psalms are different from everything you have read so far. This is not history. This is not law. This is people talking to God. Crying out. Praising. Asking why. Thanking Him. Begging for help. Declaring His faithfulness.\n\nYou are going to read fifty of them today. Some will hit you like a freight train. Some will feel repetitive. That is okay. The Psalms were never meant to be read in one sitting. But there is something about reading them in bulk that shows you the full range of what it looks like to walk with God.\n\nRead them out loud if you can. Even a few. They were written to be spoken.\n\nHalfway there. I am so proud of you.\n\nHeather"},{"day":17,"subject":"Day 17 — More Psalms. Stay with it.","reading":"Psalms 51–100","body":"Good morning.\n\nFifty more Psalms today. And I want to point you to one in particular. Psalm 51.\n\nThis is David after Bathsheba. After the prophet Nathan confronted him. And David writes the most honest prayer of repentance in the entire Bible. Create in me a clean heart, O God.\n\nThat prayer has been prayed by millions of people over thousands of years. Because we have all been there. Maybe not David's sin. But the feeling of knowing you blew it and desperately needing God to make it right.\n\nIf you are behind on reading, this is your Psalm 51 moment. Do not quit. Just come back. Read today. That is enough.\n\nHeather"},{"day":18,"subject":"Day 18 — The last of the Psalms","reading":"Psalms 101–150","body":"Good morning.\n\nLast fifty Psalms today. And they end with a crescendo.\n\nPsalm 150. Let everything that has breath praise the Lord. That is how the book of Psalms closes. After all the crying, the questioning, the anger, the grief, the doubt, it ends with praise.\n\nI think there is something in that for all of us. The journey does not end in the hard stuff. It ends in worship.\n\nYou just read the entire book of Psalms in three days. One hundred and fifty chapters. That is remarkable.\n\nEighteen days down. Thirteen to go.\n\nHeather"},{"day":19,"subject":"Day 19 — Wisdom for the rest of your life","reading":"Proverbs 1–31, Ecclesiastes 1–12, Song of Solomon 1–8","body":"Good morning.\n\nThree books today. All wisdom literature. All different.\n\nProverbs is practical. Do this, not that. Fear the Lord, get wisdom, watch your mouth, work hard. You could read one chapter of Proverbs every day for a month and your life would change.\n\nEcclesiastes is the opposite. Solomon, the wisest man alive, looking at everything and saying it is all meaningless. It sounds depressing until you realize what he is actually saying. Without God, none of it matters. That is not despair. That is the most honest thing anyone has ever written.\n\nSong of Solomon is a love poem. It is in the Bible and it is beautiful and it is supposed to be there.\n\nEnjoy today. After the weight of Job and Psalms, this is a different kind of reading.\n\nHeather"},{"day":20,"subject":"Day 20 — The prophet nobody wanted to listen to","reading":"Isaiah 1–33","body":"Good morning.\n\nYou are in the prophets now. And we start with Isaiah, the biggest of them all.\n\nIsaiah is two things at once. It is God saying to His people, you have wandered so far and judgment is coming. And it is God saying, but I am not done with you. A savior is coming. Comfort my people.\n\nToday is the first half. The harder half. Judgment. Warnings. Consequences. But even in the middle of it, you will find verses that stop you in your tracks. For unto us a child is born. That is Isaiah 9.\n\nThe prophets are harder to read than the stories. They are poetry and proclamation mixed together. Do not worry about understanding every verse. Just keep moving forward.\n\nTwenty days. You are almost there.\n\nHeather"},{"day":21,"subject":"Day 21 — Comfort, comfort my people","reading":"Isaiah 34–66","body":"Good morning. Three weeks in.\n\nToday is the second half of Isaiah. And the tone changes. Starting around chapter 40, you hit some of the most beautiful passages in the Bible.\n\nComfort, comfort my people. Those who wait on the Lord shall renew their strength. He was wounded for our transgressions. By his stripes we are healed.\n\nIsaiah wrote these words hundreds of years before Jesus. And when you read them now, knowing the rest of the story, it takes your breath away.\n\nThis might be your favorite day of reading this entire month. Let it soak in.\n\nThree weeks done. Ten days left. You are going to finish this.\n\nHeather"},{"day":22,"subject":"Day 22 — The prophet who did not want the job","reading":"Jeremiah 1–26","body":"Good morning.\n\nJeremiah was called before he was born. And his first response was, I am too young. I do not know how to speak.\n\nSound familiar? Moses said the same thing. Gideon said the same thing. Every person God calls seems to start by explaining why they are the wrong choice.\n\nJeremiah spent his entire life preaching to people who would not listen. He wept over a nation that refused to turn back. He was thrown in prison. Dropped in a muddy cistern. And he kept going.\n\nSometimes faithfulness does not look like success. Sometimes it just looks like showing up to the thing God asked you to do, even when nobody is responding.\n\nNine days left. Keep showing up.\n\nHeather"},{"day":23,"subject":"Day 23 — Jerusalem falls. Jeremiah weeps.","reading":"Jeremiah 27–52, Lamentations 1–5","body":"Good morning.\n\nToday you finish Jeremiah and read Lamentations. And it is heavy.\n\nJerusalem falls. The thing Jeremiah warned about for decades finally happens. And then Lamentations is his grief poured out on the page. Five chapters of mourning.\n\nBut right in the middle, chapter 3, you will find this. Great is His faithfulness. His mercies are new every morning.\n\nThat verse was not written on a good day. It was written in the ruins. And that is what makes it so powerful. It is not optimism. It is faith that survived the worst thing.\n\nIf you are tired today, if this challenge feels like a lot, read Lamentations 3:22-23. Mercy is new this morning. For you too.\n\nHeather"},{"day":24,"subject":"Day 24 — Visions, bones, and a valley that comes alive","reading":"Ezekiel 1–48, Daniel 1–12","body":"Good morning.\n\nBig day today. Ezekiel and Daniel.\n\nEzekiel is strange and beautiful. Wheels within wheels. A valley of dry bones that come back to life. A temple described in painstaking detail. This is a prophet who saw things no one else saw.\n\nThe valley of dry bones in chapter 37 is one of the most powerful images in all of Scripture. Can these bones live? And God says, watch me.\n\nDaniel is the lion's den. The fiery furnace. Three young men who said, our God is able to deliver us, but even if He does not, we will not bow.\n\nEven if He does not. That is the kind of faith I want.\n\nOne week left. Seven more days.\n\nHeather"},{"day":25,"subject":"Day 25 — Twelve books in one day","reading":"Hosea through Malachi","body":"Good morning.\n\nToday is the minor prophets. All twelve of them. They are called minor because they are short, not because they are less important.\n\nHosea is about a prophet told to marry an unfaithful woman as a picture of God's love for Israel. Joel is about a plague of locusts and the day of the Lord. Amos is a shepherd who told the rich to stop exploiting the poor. Jonah ran from God and ended up in a fish.\n\nMicah tells you what God requires. Do justice. Love mercy. Walk humbly.\n\nHabakkuk asks God why bad things happen and gets an answer he did not expect.\n\nMalachi is the last word of the Old Testament. And then silence. Four hundred years of silence before the New Testament begins.\n\nYou just finished the Old Testament. Let that sink in. Tomorrow you open to Matthew.\n\nHeather"},{"day":26,"subject":"Day 26 — Jesus is here","reading":"Matthew 1–28, Mark 1–16","body":"Good morning.\n\nAfter everything you have read, all the promises and prophecies and waiting, today you open to the New Testament. And the very first word of Matthew connects Jesus to Abraham and David. The whole story has been leading here.\n\nTwo Gospels today. Matthew and Mark. Matthew is detailed and teaching-heavy. The Sermon on the Mount is in chapters 5 through 7 and it will change your life if you let it. Mark is fast. He uses the word immediately more than any other writer. Everything moves.\n\nYou have spent 25 days reading about a God who promised He would come. Today He arrives.\n\nSix days left.\n\nHeather"},{"day":27,"subject":"Day 27 — Two more portraits of Jesus","reading":"Luke 1–24, John 1–21","body":"Good morning.\n\nLuke and John today. Two more Gospels. Same Jesus. Completely different angles.\n\nLuke is the historian. He tells you about the shepherds, the prodigal son, the good Samaritan, Zacchaeus in the tree. He notices the people everyone else overlooks. The poor. The women. The outsiders.\n\nJohn is the poet. In the beginning was the Word. I am the bread of life. I am the light of the world. I am the resurrection and the life. John is not trying to give you facts. He is trying to show you who Jesus really is.\n\nYou have now read all four Gospels. Four witnesses. One story. And you are four days from the finish line.\n\nHeather"},{"day":28,"subject":"Day 28 — The church explodes and Paul changes everything","reading":"Acts 1–28, Romans 1–16","body":"Good morning.\n\nActs is one of the most exciting books in the Bible. Jesus ascends. The Holy Spirit falls. Peter preaches and 3,000 people believe in a single day. And then a man named Saul, who was killing Christians, gets knocked off his horse and becomes Paul, the greatest missionary who ever lived.\n\nThe book of Acts reads like an action movie. Shipwrecks. Prison breaks. Miracles. Riots. And through all of it, the gospel spreads.\n\nThen Romans. Paul's masterpiece. This is the deepest theology in the New Testament. For all have sinned. Nothing can separate us from the love of God. Take it slow if you can. Romans is dense but every sentence matters.\n\nThree more days.\n\nHeather"},{"day":29,"subject":"Day 29 — Letters to churches that sound like they were written yesterday","reading":"1 Corinthians through Colossians","body":"Good morning.\n\nPaul's letters today. And they are surprisingly practical.\n\nCorinthians is Paul writing to a messy church. Divisions. Lawsuits. Arguments about food. And right in the middle, chapter 13, the love chapter. Love is patient. Love is kind. You have heard it at weddings. But Paul did not write it for weddings. He wrote it for a church that was tearing itself apart.\n\nGalatians is freedom. Ephesians is identity. Philippians is joy written from a prison cell. Colossians is who Jesus really is.\n\nThese letters are short. They read fast. And they will hit you differently after having read the whole Old Testament to get here. You understand now what they are building on.\n\nTwo more days.\n\nHeather"},{"day":30,"subject":"Day 30 — One more day after this","reading":"1 Thessalonians through Hebrews","body":"Good morning.\n\nPenultimate day. You are one day away from finishing.\n\nToday is the rest of Paul's letters plus Hebrews. These are shorter books. Some are only a few chapters. But they are full.\n\nThessalonians is about the return of Jesus. Timothy and Titus are Paul coaching younger leaders. Philemon is a one-page letter about a runaway slave that will break your heart.\n\nAnd then Hebrews. Nobody knows for sure who wrote it. But it ties the entire Old Testament to Jesus in a way that will make everything you have read this month click into place. Chapter 11 is the faith hall of fame. By faith Abraham. By faith Moses. By faith Rahab. These are your people now. You have read their stories.\n\nOne more day. You are going to finish this.\n\nHeather"},{"day":31,"subject":"Day 31 — You did it.","reading":"James through Revelation","body":"Good morning.\n\nThis is it. Day 31. The last day.\n\nJames is practical faith. Do not just hear the word, do it. First Peter is hope in suffering. Second Peter is holding on. John's letters are about love. Jude is a warning. And then Revelation.\n\nRevelation is wild and beautiful and confusing and hopeful all at once. Do not try to figure out every symbol. Just read it and let the ending wash over you. Because the Bible ends with a promise. He is making all things new. There will be no more tears. No more death. No more pain.\n\nThe story that started in a garden ends in a city. The story that started with God walking with two people ends with God dwelling among all His people forever.\n\nYou just read the entire Bible in 31 days.\n\nI do not know what this month has done in your heart. But I know God's Word does not return empty. Something shifted. Something grew. Something was planted that will keep growing long after today.\n\nI am so proud of you. Thank you for reading alongside me.\n\nWith love,\nHeather"}];

const EMAILS_NEW_TESTAMENT = [{"day":1,"subject":"Day 1 — Here we go. The story of Jesus starts now.","reading":"Matthew 1–9","body":"Good morning.\n\nToday is the day. You are starting the New Testament and I am reading alongside you.\n\nMatthew opens with a genealogy. It might be tempting to skip it. Do not. Because buried in that list of names are Rahab, Ruth, and Bathsheba. Women who should not be in the family tree of the Messiah. But they are. That tells you something about the kind of God we serve.\n\nThen Jesus is born. Then He is baptized. Then He walks into the wilderness for forty days. And then He starts teaching. The Sermon on the Mount begins in chapter 5 and it is some of the most powerful teaching you will ever read.\n\nNine chapters today. That is it. You can do this.\n\nHeather"},{"day":2,"subject":"Day 2 — Miracles and hard questions","reading":"Matthew 10–18","body":"Good morning.\n\nToday Jesus sends out the twelve disciples. He feeds thousands with a boy's lunch. He walks on water. Peter tries to walk on water and sinks. And Jesus asks the most important question in the entire Bible. Who do you say that I am?\n\nPeter gets it right. You are the Christ.\n\nThat question was not just for Peter. It is for you too. After everything you read yesterday and everything you will read today, the question is the same. Who do you say He is?\n\nYou are on Day 2. You showed up again. That is what matters.\n\nHeather"},{"day":3,"subject":"Day 3 — The week that changed everything","reading":"Matthew 19–28","body":"Good morning.\n\nToday you will read about the rich young ruler, the workers in the vineyard, and Jesus entering Jerusalem on a donkey. Then the tension builds. The last supper. The garden. The betrayal. The cross. The tomb.\n\nAnd then chapter 28. He is not here. He has risen.\n\nI have read this story many times. It still gets me. Every time.\n\nYou just finished your first book of the New Testament. Three days in, one Gospel done. Keep going.\n\nHeather"},{"day":4,"subject":"Day 4 — Mark does not slow down","reading":"Mark 1–8","body":"Good morning.\n\nMark is the shortest Gospel and it moves fast. The word you will see more than any other is immediately. Jesus does this, then immediately does that. Mark does not have time for long speeches. He wants you to see what Jesus did.\n\nYou will recognize stories from Matthew. That is okay. Pay attention to what Mark includes that Matthew did not. The details are different. The angle is different.\n\nMark writes like someone who is in a hurry to tell you the most important story in the world. Let him.\n\nDay 4. You are building momentum.\n\nHeather"},{"day":5,"subject":"Day 5 — The cross, again. And it hits different the second time.","reading":"Mark 9–16","body":"Good morning.\n\nYou are reading the crucifixion story for the second time in five days. And something strange happens when you read it again this soon. You notice things you missed.\n\nMark's account is rawer. Shorter. More brutal. And Mark's Gospel originally ended at chapter 16 verse 8. The women at the tomb, trembling and afraid, saying nothing to anyone.\n\nThat is a strange way to end a book. Unless the point is that the story is not over. It is your turn now.\n\nTwo Gospels done. You are almost a week in.\n\nHeather"},{"day":6,"subject":"Day 6 — Luke notices the people nobody else sees","reading":"Luke 1–6","body":"Good morning.\n\nLuke is a doctor. He is detail-oriented. And he cares about people that the other Gospel writers sometimes skip past.\n\nToday you will read about Elizabeth, an older woman who had given up on having children. About shepherds, who were nobodies. About Simeon and Anna, two elderly people waiting in the temple for something they had been promised.\n\nLuke sees the margins. The overlooked. The forgotten. If you have ever felt invisible, Luke's Gospel is for you.\n\nSix days in. You are finding your rhythm.\n\nHeather"},{"day":7,"subject":"Day 7 — One week done","reading":"Luke 7–12","body":"Good morning. One full week.\n\nToday you will read some of the most famous stories Jesus ever told. The good Samaritan. Martha and Mary. The Lord's Prayer.\n\nPause on Martha and Mary for a moment. Martha is doing all the work. Mary is sitting at the feet of Jesus. And Jesus says Mary chose the better thing.\n\nThat is hard to hear when you are the one doing all the work. But I think the point is not that doing is wrong. It is that there are moments when the most important thing is to stop and sit.\n\nThis might be one of those moments. You have been reading for seven days straight. Take a breath. Sit with what you have read. You are doing so well.\n\nHeather"},{"day":8,"subject":"Day 8 — Lost things and found things","reading":"Luke 13–18","body":"Good morning.\n\nToday you will read the prodigal son. Luke 15. It is the most famous parable Jesus ever told and it still wrecks me.\n\nA son takes his inheritance, wastes it, ends up feeding pigs, and comes home expecting to be a servant. And the father runs to him. Does not wait. Does not lecture. Runs.\n\nI have been the prodigal. I have been the older brother too. And the thing that gets me every time is the father. He was watching. He was waiting. He ran.\n\nThat is how God feels about you. Right now. Today.\n\nHeather"},{"day":9,"subject":"Day 9 — The cross, the third time. What do you see now?","reading":"Luke 19–24","body":"Good morning.\n\nThis is the third time you are reading the death and resurrection of Jesus. And I want to ask you something. What are you noticing now that you did not notice the first time?\n\nLuke includes things the others do not. Jesus sweating drops of blood in the garden. Telling the thief on the cross, today you will be with me in paradise. Walking with two disciples on the road to Emmaus after the resurrection, and they did not even recognize Him until He broke bread.\n\nThat last one gets me. Sometimes Jesus is right next to you and you do not see it until later.\n\nThree Gospels done. You are almost a third of the way through the New Testament.\n\nHeather"},{"day":10,"subject":"Day 10 — John sees something the others did not","reading":"John 1–7","body":"Good morning.\n\nJohn is different. You will feel it immediately.\n\nIn the beginning was the Word, and the Word was with God, and the Word was God.\n\nNo genealogy. No birth story. John starts before the beginning of time. Because John is not trying to tell you what Jesus did. He is trying to show you who Jesus is.\n\nToday you will read about water turned to wine, Nicodemus coming to Jesus at night, the woman at the well, and Jesus feeding five thousand. But John frames each one as a sign. A glimpse of something bigger.\n\nTen days in. One third done. You are in this.\n\nHeather"},{"day":11,"subject":"Day 11 — I am","reading":"John 8–14","body":"Good morning.\n\nToday you will read some of the most powerful words Jesus ever spoke. I am the light of the world. I am the good shepherd. I am the resurrection and the life. I am the way, the truth, and the life.\n\nEvery one of those I am statements would have hit the people listening like a thunderbolt. Because they knew that I AM was the name God gave Himself when Moses asked at the burning bush.\n\nJesus was not being subtle. He was saying exactly who He was.\n\nChapter 11 is the raising of Lazarus. And right before He does it, Jesus weeps. He already knew He was about to raise His friend from the dead. And He still cried. Because He felt the grief.\n\nThat is the kind of God you are reading about.\n\nHeather"},{"day":12,"subject":"Day 12 — The upper room and the empty tomb","reading":"John 15–21","body":"Good morning.\n\nJohn 15 through 17 is Jesus talking to His closest friends the night before He dies. And it is the most intimate conversation in the Bible. I am the vine. Abide in me. I call you friends. I am praying for you.\n\nThen the cross. Then the tomb. Then Mary Magdalene in the garden, weeping, and Jesus says her name. Mary. And she knows.\n\nThen Thomas, who doubted, gets to put his hands in the wounds. And Peter, who denied Jesus three times, gets asked three times, do you love me?\n\nFour Gospels done. You have seen Jesus from four angles. Tomorrow the church begins.\n\nHeather"},{"day":13,"subject":"Day 13 — The Holy Spirit shows up and everything changes","reading":"Acts 1–7","body":"Good morning.\n\nJesus ascends. The disciples wait. And then the Holy Spirit falls on them like fire and they start speaking in languages they have never learned and Peter, the man who denied Jesus, stands up and preaches and three thousand people believe.\n\nThat is Acts chapter 2. And the rest of the book just keeps going.\n\nToday you will also read about Stephen, the first person killed for following Jesus. His last words were, Lord, do not hold this sin against them. Just like Jesus on the cross.\n\nActs is the most exciting book in the New Testament. It reads like an adventure story. Because it is one.\n\nHeather"},{"day":14,"subject":"Day 14 — Two weeks in. Paul enters the story.","reading":"Acts 8–14","body":"Good morning. Two weeks.\n\nToday a man named Saul, who has been hunting Christians and throwing them in prison, gets knocked off his horse by a blinding light. And Jesus says, Saul, Saul, why are you persecuting me?\n\nSaul becomes Paul. And the entire trajectory of Christianity changes because of it.\n\nI love this story because it proves that nobody is too far gone. The guy who was the worst enemy of the church became its greatest champion. If God can use Paul, He can use anyone.\n\nYou are halfway through the challenge. Fourteen days done. Fourteen to go.\n\nHeather"},{"day":15,"subject":"Day 15 — Missionary journeys and midnight worship","reading":"Acts 15–21","body":"Good morning.\n\nPaul is on the move today. City after city. Shipwrecks. Beatings. Prison. And in chapter 16, Paul and Silas are sitting in a jail cell at midnight, bleeding from being beaten, and they start singing.\n\nSinging. In prison. At midnight. After being beaten.\n\nAnd then an earthquake breaks the chains and the jailer falls to his knees and asks, what must I do to be saved?\n\nThat is the power of worship in the dark places. It does not just change you. It changes the people watching.\n\nFifteen days down. You are in the second half now.\n\nHeather"},{"day":16,"subject":"Day 16 — Paul will not stop","reading":"Acts 22–28","body":"Good morning.\n\nPaul gets arrested. Put on trial. Appealed to Caesar. Shipwrecked on the way to Rome. Bitten by a snake on the island. And he just keeps going.\n\nThe book of Acts ends with Paul in Rome, under house arrest, still preaching the gospel. Still teaching. Still unhindered.\n\nThat is the last word of Acts. Unhindered. The gospel cannot be stopped. Not by chains. Not by storms. Not by snakes. Not by Rome.\n\nYou just finished Acts. Tomorrow you start Paul's letters. This is where it gets personal.\n\nHeather"},{"day":17,"subject":"Day 17 — The deepest theology Paul ever wrote","reading":"Romans 1–8","body":"Good morning.\n\nRomans is dense. I am not going to pretend otherwise. Paul is building an argument, brick by brick, about sin and grace and faith and salvation.\n\nBut chapter 8 is where it all lands. And chapter 8 might be the single greatest chapter in the entire Bible.\n\nThere is no condemnation for those who are in Christ Jesus. All things work together for good. Nothing can separate us from the love of God.\n\nIf you only remember one chapter from this entire challenge, make it Romans 8.\n\nSeventeen days. You have read more of the Bible than most people read in a lifetime.\n\nHeather"},{"day":18,"subject":"Day 18 — Grace changes everything","reading":"Romans 9–16","body":"Good morning.\n\nThe second half of Romans shifts from theology to practice. Paul is saying, okay, you understand grace. Now here is what it looks like to live it.\n\nChapter 12 is one of the most practical chapters in the Bible. Love sincerely. Hate evil. Be joyful in hope. Patient in affliction. Faithful in prayer. Bless those who persecute you. Do not repay evil for evil.\n\nThat is not a suggestion. That is what grace looks like when it hits the ground.\n\nEighteen down. You are in a groove. Keep it.\n\nHeather"},{"day":19,"subject":"Day 19 — Paul writes to a messy church","reading":"1 Corinthians 1–8","body":"Good morning.\n\nCorinth was a mess. The church was divided. People were suing each other. There were arguments about everything.\n\nAnd Paul does not start by yelling at them. He starts by reminding them who they are. You are called. You are sanctified. You belong to Christ.\n\nThat is always God's approach. Before He corrects you, He reminds you who you are.\n\nToday's reading is Paul dealing with real problems in a real church. It sounds like it could have been written last week. People have not changed much in two thousand years.\n\nTwelve days left.\n\nHeather"},{"day":20,"subject":"Day 20 — Love and resurrection","reading":"1 Corinthians 9–16","body":"Good morning. Twenty days in.\n\nToday you hit two of the most famous chapters in the Bible. Chapter 13, the love chapter. And chapter 15, the resurrection chapter.\n\nLove is patient. Love is kind. You have heard it before. But read it today as Paul writing to people who were anything but patient and kind. It is not a poem about romance. It is a mirror held up to a church that needed to hear it.\n\nAnd chapter 15. If Christ has not been raised, your faith is useless. But Christ has been raised. And because He has, everything changes.\n\nTwenty days. Eleven to go. You are so close.\n\nHeather"},{"day":21,"subject":"Day 21 — Three weeks. Strength in weakness.","reading":"2 Corinthians 1–7","body":"Good morning. Three full weeks.\n\nSecond Corinthians is Paul at his most vulnerable. He talks about being crushed. Despairing of life. Carrying the sentence of death within himself.\n\nAnd then he says this. We have this treasure in jars of clay to show that the surpassing power belongs to God and not to us.\n\nJars of clay. Fragile. Cracked. Ordinary. But carrying something extraordinary.\n\nThat is you. That is me. We are not the treasure. We carry it. And the cracks are how the light gets out.\n\nThree weeks done. You are in the home stretch.\n\nHeather"},{"day":22,"subject":"Day 22 — Freedom","reading":"2 Corinthians 8–13, Galatians 1–6","body":"Good morning.\n\nYou finish Second Corinthians today and then read all of Galatians. And Galatians is about one thing. Freedom.\n\nPaul is furious. People are telling the Galatian Christians that they need to follow the Jewish law to be saved. And Paul says no. Absolutely not. Christ set you free. Do not go back to slavery.\n\nIt is for freedom that Christ has set us free. Stand firm, then, and do not let yourselves be burdened again by a yoke of slavery.\n\nThat verse changed my life. Because I am really good at putting chains back on myself that God already removed.\n\nNine days left.\n\nHeather"},{"day":23,"subject":"Day 23 — Who you are in Christ","reading":"Ephesians 1–6, Philippians 1–4, Colossians 1–4","body":"Good morning.\n\nThree letters today. Ephesians, Philippians, and Colossians. They are short. They are powerful. And they all answer the same question. Who are you now that you belong to Christ?\n\nEphesians says you are chosen, adopted, sealed, and seated with Christ. Philippians says you can do all things through Christ who strengthens you. Colossians says Christ is before all things and in Him all things hold together.\n\nPhilippians was written from prison. And it is the most joyful book in the New Testament. Paul says the word joy or rejoice sixteen times in four chapters. From a jail cell.\n\nJoy is not about circumstances. It never has been.\n\nEight days left.\n\nHeather"},{"day":24,"subject":"Day 24 — Letters to friends and a young pastor","reading":"1–2 Thessalonians, 1 Timothy","body":"Good morning.\n\nThessalonians is Paul writing to a church he loves about the return of Jesus. He is answering their questions. What happens to the people who have already died? When is Jesus coming back?\n\nAnd his answer is essentially, I do not know when. But I know He is. So live ready.\n\nFirst Timothy is Paul writing to a young pastor he mentored. It is personal. Practical. Don't let anyone look down on you because you are young. Fight the good fight. Guard what has been entrusted to you.\n\nIf you are a leader, or raising one, First Timothy will speak to you today.\n\nOne week left.\n\nHeather"},{"day":25,"subject":"Day 25 — Paul's last letter and a one-page masterpiece","reading":"2 Timothy 1–4, Titus 1–3, Philemon","body":"Good morning.\n\nSecond Timothy is Paul's last letter. He is in prison. He knows he is going to die. And he writes to Timothy one final time.\n\nI have fought the good fight. I have finished the race. I have kept the faith.\n\nThat is how Paul says goodbye. Not with regret. Not with fear. With confidence that he did what he was called to do.\n\nTitus is short and practical. And Philemon is one page. One single page about a runaway slave named Onesimus. Paul asks his friend to take Onesimus back, not as a slave but as a brother. It is the gospel in miniature.\n\nSix days to go.\n\nHeather"},{"day":26,"subject":"Day 26 — The Old Testament finally makes sense","reading":"Hebrews 1–13","body":"Good morning.\n\nHebrews ties everything together. If you have ever wondered what the Old Testament sacrifices and priests and temples were all about, Hebrews is the answer. They were all pointing to Jesus.\n\nChapter 11 is the faith hall of fame. By faith Abraham left everything. By faith Moses chose suffering over comfort. By faith Rahab welcomed the spies. These are real people who trusted God when they could not see the outcome.\n\nAnd chapter 12 says you are surrounded by this great cloud of witnesses. Every person of faith who came before you is cheering you on.\n\nFive days left. You are almost there.\n\nHeather"},{"day":27,"subject":"Day 27 — Faith that does something","reading":"James 1–5, 1 Peter 1–5, 2 Peter 1–3","body":"Good morning.\n\nJames does not mess around. Faith without works is dead. Do not just listen to the word. Do what it says. Control your tongue. Care for the poor. Be patient.\n\nJames is the most practical book in the New Testament. It is faith with its sleeves rolled up.\n\nFirst Peter is about hope in the middle of suffering. Written to people who were being persecuted for their faith. And Peter says, do not be surprised. But do not lose hope either.\n\nSecond Peter is about holding onto the truth when everything around you is trying to pull you away.\n\nFour more days.\n\nHeather"},{"day":28,"subject":"Day 28 — Love. That is the whole thing.","reading":"1 John 1–5, 2 John, 3 John, Jude","body":"Good morning.\n\nJohn, the disciple who called himself the one Jesus loved, writes three short letters. And the theme is love.\n\nGod is love. If we love one another, God lives in us. There is no fear in love. Perfect love drives out fear.\n\nAfter all the theology and the history and the letters and the arguments, it comes down to this. Love God. Love people. That is the whole thing.\n\nJude is one chapter. A warning to hold onto your faith. Short and fierce.\n\nThree days left. You are about to finish the New Testament.\n\nHeather"},{"day":29,"subject":"Day 29 — The beginning of the end","reading":"Revelation 1–8","body":"Good morning.\n\nRevelation. The last book of the Bible. And it is unlike anything else you have read.\n\nDo not try to decode every symbol. Do not try to build a timeline. Just read it. Let the images wash over you. The throne room. The lamb. The scrolls. The worship.\n\nBecause before Revelation gets to the scary parts, it starts with worship. Chapter 4 and 5 are the most magnificent picture of heaven in all of Scripture. Holy, holy, holy is the Lord God Almighty, who was and is and is to come.\n\nThat is where the story is heading. Not chaos. Worship.\n\nTwo more days.\n\nHeather"},{"day":30,"subject":"Day 30 — Hold on. Almost there.","reading":"Revelation 9–16","body":"Good morning.\n\nThis is the hardest stretch of Revelation. Seals and trumpets and bowls and beasts. It is intense.\n\nBut here is what I want you to hold onto today. In the middle of all of it, there are moments of worship. Moments where the story pauses and the heavens sing. The kingdom of the world has become the kingdom of our Lord and of His Christ, and He shall reign forever and ever.\n\nThe darkness in Revelation is not the point. The darkness is the backdrop for the light.\n\nOne more day. Tomorrow you finish.\n\nHeather"},{"day":31,"subject":"Day 31 — You did it.","reading":"Revelation 17–22","body":"Good morning.\n\nThis is it. The last day. The last chapters.\n\nToday you will read about the fall of Babylon, the return of Jesus, and the new heaven and the new earth. And the Bible ends with this.\n\nHe will wipe every tear from their eyes. There will be no more death or mourning or crying or pain, for the old order of things has passed away. He who was seated on the throne said, I am making everything new.\n\nThat is how the story ends. Not with destruction. With restoration. Not with tears. With every tear wiped away.\n\nYou just read the entire New Testament in 31 days.\n\nI do not know what stood out to you most. I do not know which verse stopped you in your tracks or which story you cannot stop thinking about. But I know something happened this month. God's Word does not come back empty.\n\nThank you for doing this with me. Thank you for showing up for 31 days. I am so proud of you.\n\nWith love,\nHeather"}];

async function hmacHex(secret, message) {
  const enc = new TextEncoder();
  const key = await crypto.subtle.importKey(
    "raw", enc.encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]
  );
  const sig = await crypto.subtle.sign("HMAC", key, enc.encode(message));
  return [...new Uint8Array(sig)].map(b => b.toString(16).padStart(2, "0")).join("");
}

function getEasternDate() {
  const now = new Date();
  return now.toLocaleDateString("en-CA", { timeZone: "America/New_York" });
}

function getDayNumber() {
  const eastern = getEasternDate();
  const today = new Date(eastern + "T00:00:00");
  const diffMs = today - CHALLENGE_START;
  if (diffMs < 0) return 0;
  return Math.floor(diffMs / 86400000) + 1;
}

function buildEmailHtml(name, dayNum, email, reading, body, dashboardUrl, communityCount, unsubUrl) {
  const paragraphs = body.split("\n\n").map(p => {
    if (p === "Heather" || p === "With love,\nHeather") {
      return `<p style="margin:12px 0 0;font-size:18px;color:#1f2937;font-style:italic;font-family:Georgia,serif;">${p.replace("\n", "<br>")}</p>`;
    }
    return `<p style="margin:0 0 16px;font-size:16px;color:#4b5563;line-height:1.7;font-family:-apple-system,sans-serif;">${p}</p>`;
  }).join("\n");

  return `<!DOCTYPE html>
<html>
<head><meta charset="UTF-8"></head>
<body style="margin:0;padding:0;background:#f7f4ee;font-family:Georgia,'Times New Roman',serif;">
<table width="100%" cellpadding="0" cellspacing="0" style="background:#f7f4ee;padding:40px 0;">
<tr><td align="center">
<table width="580" cellpadding="0" cellspacing="0" style="background:#ffffff;border-radius:8px;overflow:hidden;">

<tr><td style="background:#1f2937;padding:28px 32px;">
<span style="color:#ffffff;font-size:20px;font-family:Georgia,serif;letter-spacing:0.5px;">HeatherLynWilson.com</span>
<span style="float:right;color:#c8a365;font-size:13px;font-family:-apple-system,sans-serif;font-weight:600;padding-top:4px;">DAY ${dayNum} OF 31</span>
</td></tr>

<tr><td style="padding:28px 32px 8px;">
<p style="margin:0 0 4px;font-size:12px;color:#b85638;font-family:-apple-system,sans-serif;font-weight:600;letter-spacing:1px;text-transform:uppercase;">TODAY'S READING</p>
<p style="margin:0 0 20px;font-size:22px;color:#1f2937;font-family:Georgia,serif;font-weight:600;">${reading}</p>
</td></tr>

<tr><td style="padding:0 32px 24px;">
${paragraphs}
</td></tr>

<tr><td style="padding:0 32px 28px;" align="center">
<a href="${dashboardUrl}" style="display:inline-block;padding:14px 32px;background:#b85638;color:#ffffff;text-decoration:none;border-radius:6px;font-size:15px;font-family:-apple-system,sans-serif;font-weight:600;">Check Off Today's Reading</a>
</td></tr>

${communityCount > 0 ? `<tr><td style="padding:0 32px 24px;text-align:center;">
<p style="margin:0;font-size:14px;color:#6b7280;font-family:-apple-system,sans-serif;">${communityCount} ${communityCount === 1 ? "person has" : "people have"} already checked in today.</p>
</td></tr>` : ""}

<tr><td style="padding:0 32px 24px;text-align:center;">
<p style="margin:0;font-size:14px;color:#6b7280;font-family:-apple-system,sans-serif;">Know someone who would want to read along? <a href="${SITE}/challenge" style="color:#b85638;">heatherlynwilson.com/challenge</a></p>
</td></tr>

<tr><td style="padding:24px 32px 32px;border-top:1px solid #e5e0d5;">
<p style="margin:0;font-size:12px;color:#6b7280;font-family:-apple-system,sans-serif;line-height:1.5;">
You are receiving this because you signed up for the July Bible Challenge at heatherlynwilson.com.${unsubUrl ? `<br><a href="${unsubUrl}" style="color:#6b7280;">Unsubscribe</a>` : ""}
</p>
</td></tr>

</table>
</td></tr>
</table>
</body>
</html>`;
}

export default {
  async scheduled(event, env) {
    const dayNum = getDayNumber();
    if (dayNum < 1 || dayNum > 31) {
      console.log(`Day ${dayNum} is outside challenge range. Skipping.`);
      return;
    }

    console.log(`Sending Day ${dayNum} challenge emails...`);

    // Get all signups
    const { results } = await env.DB.prepare(
      "SELECT name, email, track FROM challenge_signups WHERE challenge = ?"
    ).bind(CHALLENGE).all();

    if (!results || results.length === 0) {
      console.log("No signups found.");
      return;
    }

    // Get today's community check-in count (from yesterday since emails go out early)
    let communityCount = 0;
    try {
      const row = await env.DB.prepare(
        "SELECT COUNT(DISTINCT email) as cnt FROM challenge_checkins WHERE day = ? AND challenge = ?"
      ).bind(dayNum > 1 ? dayNum - 1 : 1, CHALLENGE).first();
      communityCount = row ? row.cnt : 0;
    } catch (e) {}

    const secret = env.NOTIFY_SECRET || "challenge-secret";
    const validUntil = "2026-10-01";
    let sent = 0;
    let errors = 0;

    // Send in batches of 10 to avoid rate limits
    for (let i = 0; i < results.length; i += 10) {
      const batch = results.slice(i, i + 10);
      const promises = batch.map(async (user) => {
        const track = user.track || "full-bible";
        const emails = track === "new-testament" ? EMAILS_NEW_TESTAMENT : EMAILS_FULL_BIBLE;
        const emailData = emails[dayNum - 1];
        if (!emailData) return;

        const name = user.name || "friend";
        const email = user.email;

        // Generate dashboard link
        const dashToken = await hmacHex(secret, email + ":challenge:" + validUntil);
        const dashboardUrl = `${SITE}/challenge/dashboard.html?email=${encodeURIComponent(email)}&token=${dashToken}`;

        // Generate unsubscribe link
        const unsubToken = await hmacHex(secret, email);
        const unsubUrl = `${SITE}/api/unsubscribe?email=${encodeURIComponent(email)}&token=${unsubToken}`;

        const subject = emailData.subject;
        const bodyText = emailData.body.replace("Good morning.", `Good morning, ${name}.`);
        const htmlContent = buildEmailHtml(name, dayNum, email, emailData.reading, bodyText, dashboardUrl, communityCount, unsubUrl);

        try {
          const res = await fetch("https://api.brevo.com/v3/smtp/email", {
            method: "POST",
            headers: {
              "api-key": env.BREVO_API_KEY,
              "Content-Type": "application/json",
            },
            body: JSON.stringify({
              sender: { name: "Heather Lyn Wilson", email: "heather@heatherlynwilson.com" },
              to: [{ email: email, name: name }],
              subject: subject,
              htmlContent: htmlContent,
            }),
          });
          if (res.ok) {
            sent++;
          } else {
            errors++;
            const text = await res.text();
            console.error(`Failed to send to ${email}: ${res.status} ${text}`);
          }
        } catch (e) {
          errors++;
          console.error(`Error sending to ${email}: ${e.message}`);
        }
      });

      await Promise.allSettled(promises);
    }

    console.log(`Day ${dayNum} emails complete. Sent: ${sent}, Errors: ${errors}, Total: ${results.length}`);
  },
};
